def mover_fotos_existentes(apps, schema_editor):
    """
    Las fotos de antes de este cambio pasan a la tabla nueva como fotos
    GENERALES del servicio (sin sede): la que iba en el adjunto único de la
    orden y las que quedaron como documentos «Registro fotográfico (...)».
    Los archivos no se mueven: la fila nueva apunta al mismo nombre en el
    storage. Los documentos ya copiados se quitan de DocumentoOrden para que
    no salgan dos veces en el expediente.
    """
    OrdenServicio = apps.get_model('gestion', 'OrdenServicio')
    DocumentoOrden = apps.get_model('gestion', 'DocumentoOrden')
    FotoRegistro = apps.get_model('gestion', 'FotoRegistro')
    for orden in (OrdenServicio.objects
                  .exclude(registro_fotografico_adjunto__isnull=True)
                  .exclude(registro_fotografico_adjunto='')):
        foto = FotoRegistro.objects.create(
            orden=orden, archivo=orden.registro_fotografico_adjunto.name,
            nota='Foto 1 (antes del registro por sede)')
        FotoRegistro.objects.filter(pk=foto.pk).update(subido_en=orden.fecha_creacion)
    for doc in (DocumentoOrden.objects
                .filter(descripcion__startswith='Registro fotográfico')
                .order_by('fecha_subida', 'pk')):
        foto = FotoRegistro.objects.create(
            orden_id=doc.orden_id, archivo=doc.archivo.name, nota=doc.descripcion)
        FotoRegistro.objects.filter(pk=foto.pk).update(subido_en=doc.fecha_subida)
        doc.delete()


